def fib(n):
    """n-te Fibonacci-Zahl (iterativ)."""
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

from mathe import fib


def test_fib_basis():
    assert fib(0) == 0
    assert fib(1) == 1


def test_fib_reihe():
    assert [fib(i) for i in range(7)] == [0, 1, 1, 2, 3, 5, 8]

